using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class BuildThanksChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var actors=slice.GetComponentsInChildren<VillagerExploration>();var actor=actors[0];var nav=actor.GetComponent<IslandNavigator>();Require(!nav.world.TreeNavigationPending,"Wait for navigation");var stateField=typeof(QuestSlice).GetField("state",Flags);var original=stateField.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused;var positions=actors.Select(a=>a.transform.position).ToArray();var rotations=actors.Select(a=>a.transform.rotation).ToArray();var godAt=god.transform.position;var godFacing=god.transform.rotation;var peers=(VillagerExploration[])typeof(VillagerExploration).GetField("neighbors",Flags).GetValue(actor);var test=new SliceState();
  SocialMemory Memory()=>actor.GetComponent<VillagerSocial>().Memory;
  void Stage(int creaturePieces,bool rain=false){
   foreach(var a in actors){a.ResetTask();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();a.GetComponent<VillagerResourceGathering>().Cancel();a.GetComponent<CarryItem>().held=false;}
   god.Interrupt("Build thanks fixture");test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};test.Hybrid.time=100;test.Weather.rain=rain?1:0;stateField.SetValue(slice,test);slice.GetComponentInChildren<VillageFamilies>().ResetWorld();site.Paused=false;site.ResetConstruction();site.Recipe=BuildRecipe.Bench;actor.ConfigurePeers(Array.Empty<VillagerExploration>());
   for(int i=0;i<actors.Length;i++){actors[i].transform.position=positions[i]+Vector3.up*nav.world.Scale*500;actors[i].GetComponent<IslandNavigator>().ResetRoute();}
   Require(nav.world.Sample(site.World(new Vector3(0,0,-12)),nav.profile,12,out var foot),"No visitor staging point");actor.transform.position=nav.world.ProjectFoot(foot,nav.profile);nav.ResetRoute();var godNav=god.GetComponent<IslandNavigator>();Require(nav.world.Sample(site.World(new Vector3(10,0,-18)),godNav.profile,12,out var godFoot),"No benefactor staging point");god.transform.position=nav.world.ProjectFoot(godFoot,godNav.profile);godNav.ResetRoute();
   int n=0;foreach(var p in ConstructionPatterns.Plan(BuildRecipe.Bench)){var b=site.blocks.First(b=>!b.Attached&&(b.Shape==ConstructionShape.Beam)==p.beam&&b.RecipePiece);test.Hybrid.time+=1;Require(site.Drop(b,site.World(p.position),site.transform.rotation,n<creaturePieces,n<creaturePieces?null:"player"),"Bench fixture failed");n++;}Memory().restNeed=.9f;
  }
  void Step(){test.Hybrid.time+=.05f;actor.Tick(.05f,false);}
  void Visit(){int before=Memory().constructionUses;Require(actor.TryStructure(site),"Native structure visit rejected");for(int i=0;i<1600&&Memory().constructionUses==before;i++)Step();Require(Memory().constructionUses==before+1&&site.Visitor==null,"Native use never completed / visitor lease leaked");}
  try{
   Require(new SocialMemory().Valid(),"Old social save invalid");Stage(2);Require(Mathf.Abs(site.CreatureRecipeShare-2f/3)<.001f,"Mixed contribution fraction wrong");var extra=site.blocks.First(b=>!b.Attached&&b.Shape==ConstructionShape.Cube);Require(site.Drop(extra,site.World(new Vector3(10,extra.size.y*.5f,8)),site.transform.rotation,true),"Decorative staging failed");Require(Mathf.Abs(site.CreatureRecipeShare-2f/3)<.001f,"Decorative block distorted contribution");float trust=Memory().trust,preference=test.Building.preference[(int)BuildRecipe.Bench];Visit();Require(Mathf.Abs(Memory().trust-trust-.04f)<.001f&&Mathf.Abs(test.Building.preference[(int)BuildRecipe.Bench]-preference-.08f)<.001f&&Memory().helpfulBuildUses==1&&actor.Current==VillagerExploration.Phase.BuildThanks,"Mixed native use did not earn proportional credit / thanks");var at=actor.transform.position;actor.Tick(4,true);Require(actor.transform.position==at&&Memory().buildThanks==0,"Paused thank-you advanced");
   bool gestured=false;var hands=actor.GetComponentInChildren<HumanoidHands>();for(int i=0;i<600&&Memory().buildThanks==0;i++){Step();gestured|=hands!=null&&hands.beckon;}Require(gestured&&Memory().buildThanks==1&&actor.Current==VillagerExploration.Phase.Celebrate,"Villager did not approach and finish visible thank-you");Require((float)typeof(VillagerAffect).GetField("loveUntil",Flags).GetValue(actor.GetComponent<VillagerAffect>())>test.Hybrid.time,"Thanks did not signal positive affect");float earned=Memory().trust;actor.ResetTask();Visit();Require(Memory().trust==earned&&Memory().helpfulBuildUses==1&&Memory().buildThanks==1,"Repeated form farmed gratitude");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.relationships[0].buildThanks==1,"Thanks memory did not save");saved.relationships[0].buildThanks=2;Require(!saved.Valid(),"Fabricated thanks accepted");saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));saved.relationships[0].helpfulBuildUses=saved.relationships[0].constructionUses+1;Require(!saved.Valid(),"Helpful uses exceed actual visits");
   Stage(0);trust=Memory().trust;Visit();Require(Memory().trust==trust&&Memory().helpfulBuildUses==0&&actor.Current!=VillagerExploration.Phase.BuildThanks&&Memory().restNeed<.9f,"Player-only useful work credited to creature / lost rest benefit");
   Stage(3,true);trust=Memory().trust;Visit();Require(Memory().trust==trust&&Memory().helpfulBuildUses==0&&actor.Current!=VillagerExploration.Phase.BuildThanks,"Exposed rainy bench earned positive creature credit");
   Stage(3);trust=Memory().trust;Visit();Require(Mathf.Abs(Memory().trust-trust-.06f)<.001f&&actor.Current==VillagerExploration.Phase.BuildThanks,"Fully creature-built use lost existing credit");actor.GetComponent<CarryItem>().held=true;Step();Require(actor.Current==VillagerExploration.Phase.Idle&&Memory().buildThanks==0&&!hands.beckon,"Pickup did not cancel transient thank-you");actor.GetComponent<CarryItem>().held=false;
   Stage(2);Visit();Memory().injury=.3f;Step();Require(actor.Current==VillagerExploration.Phase.Idle&&Memory().buildThanks==0,"Injury did not cancel thanks");
   Stage(2);var support=site.blocks.First(b=>b.Attached&&b.Shape==ConstructionShape.Brick);support.Grab();Require(site.CreatureRecipeShare==0&&!actor.TryStructure(site)&&Memory().helpfulBuildUses==0,"Incomplete form gained contribution/use credit");
   Debug.Log("BWVR_BUILD_THANKS_PASS: real mixed/solo/full/rainy structure use, recipe-only fractional trust/learning, first-form guard, approach/gesture/love cue, pause/carry/injury cleanup, bounded saved outcomes and incomplete-structure rejection");
  }finally{actor.GetComponent<CarryItem>().held=false;foreach(var a in actors)a.ResetTask();site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;actor.ConfigurePeers(peers);for(int i=0;i<actors.Length;i++){actors[i].transform.SetPositionAndRotation(positions[i],rotations[i]);actors[i].GetComponent<IslandNavigator>().ResetRoute();}god.Interrupt("Build thanks QA complete");god.transform.SetPositionAndRotation(godAt,godFacing);god.GetComponent<IslandNavigator>().ResetRoute();stateField.SetValue(slice,original);}
 }
}
}
